// i18n.php — full i18n for Prismatch (19 languages)

function supported_languages() {
  return [
    'en' => 'English',
    'tr' => 'Türkçe',
    'zh-CN' => '中文(简体)',
    'es' => 'Español',
    'hi' => 'हिन्दी',
    'pt' => 'Português',
    'bn' => 'বাংলা',
    'ru' => 'Русский',
    'ja' => '日本語',
    'vi' => 'Tiếng Việt',
    'yue' => '粵語',
    'ar' => 'العربية',
    'wuu' => '吴语',
    'ko' => '한국어',
    'de' => 'Deutsch',
    'id' => 'Bahasa Indonesia',
    'fr' => 'Français',
    'fa' => 'فارسی',
    'it' => 'Italiano',
  ];
}

function lang_dir($lang) {
  return in_array($lang, ['ar','fa'], true) ? 'rtl' : 'ltr';
}

function locale_for_lang($lang) {
  switch ($lang) {
    case 'tr': return 'tr_TR';
    case 'en': return 'en_US';
    case 'es': return 'es_ES';
    case 'pt': return 'pt_PT';
    case 'fr': return 'fr_FR';
    case 'de': return 'de_DE';
    case 'it': return 'it_IT';
    case 'ru': return 'ru_RU';
    case 'ar': return 'ar_SA';
    case 'fa': return 'fa_IR';
    case 'hi': return 'hi_IN';
    case 'bn': return 'bn_BD';
    case 'id': return 'id_ID';
    case 'vi': return 'vi_VN';
    case 'ja': return 'ja_JP';
    case 'ko': return 'ko_KR';
    case 'zh-CN': return 'zh_CN';
    case 'yue': return 'zh_HK';
    case 'wuu': return 'zh_CN';
    default: return 'en_US';
  }
}

function format_dt_local($utcIso, $lang = null) {
  if (!$utcIso) return '-';
  $lang = $lang ? $lang : get_lang();
  $locale = locale_for_lang($lang);

  try {
    $dt = new DateTimeImmutable($utcIso, new DateTimeZone('UTC'));
    $tz = isset($_SESSION['browser_timezone']) ? $_SESSION['browser_timezone'] : (isset($_COOKIE['tz']) ? $_COOKIE['tz'] : 'UTC');
    if (!in_array($tz, timezone_identifiers_list(), true)) $tz = 'UTC';
    $dt = $dt->setTimezone(new DateTimeZone($tz));

    if ($lang === 'tr') {
      return $dt->format('d/m/Y H:i');
    }

    if (class_exists('IntlDateFormatter')) {
      $fmt = new IntlDateFormatter($locale, IntlDateFormatter::SHORT, IntlDateFormatter::SHORT, $tz);
      return $fmt->format($dt);
    }
    return $dt->format('Y-m-d H:i');
  } catch (Exception $e) {
    return '-';
  }
}

function format_num_local($value, $lang = null, $decimals = 0) {
  $lang = $lang ? $lang : get_lang();
  $locale = locale_for_lang($lang);

  if (class_exists('NumberFormatter')) {
    $nf = new NumberFormatter($locale, NumberFormatter::DECIMAL);
    $nf->setAttribute(NumberFormatter::FRACTION_DIGITS, $decimals);
    $out = $nf->format($value);
    if ($out !== false) return $out;
  }
  return number_format((float)$value, $decimals, '.', ',');
}

function lang_flag($lang) {
  switch ($lang) {
    case 'en': return '🇺🇸';
    case 'tr': return '🇹🇷';
    case 'es': return '🇪🇸';
    case 'pt': return '🇵🇹';
    case 'fr': return '🇫🇷';
    case 'de': return '🇩🇪';
    case 'it': return '🇮🇹';
    case 'ru': return '🇷🇺';
    case 'ar': return '🇸🇦';
    case 'fa': return '🇮🇷';
    case 'hi': return '🇮🇳';
    case 'bn': return '🇧🇩';
    case 'id': return '🇮🇩';
    case 'vi': return '🇻🇳';
    case 'ja': return '🇯🇵';
    case 'ko': return '🇰🇷';
    case 'zh-CN': return '🇨🇳';
    case 'yue': return '🇭🇰';
    case 'wuu': return '🇨🇳';
    default: return '🌐';
  }
}

function normalize_lang($raw) {
  $raw = trim($raw);
  if ($raw === '') return 'en';
  $raw = str_replace('_', '-', $raw);
  if (stripos($raw, 'zh') === 0) return 'zh-CN';
  $parts = explode('-', $raw);
  return isset($parts[0]) ? $parts[0] : 'en';
}

function detect_browser_lang() {
  $supported = array_keys(supported_languages());
  $al = isset($_SERVER['HTTP_ACCEPT_LANGUAGE']) ? $_SERVER['HTTP_ACCEPT_LANGUAGE'] : '';
  if ($al) {
    $cands = explode(',', $al);
    foreach ($cands as $c) {
      $code = trim(explode(';', $c)[0]);
      if ($code === '') continue;
      if (in_array($code, $supported, true)) return $code;
      $base = normalize_lang($code);
      if (in_array($base, $supported, true)) return $base;
    }
  }
  return 'en';
}

function get_lang() {
  $supported = array_keys(supported_languages());
  if (!empty($_SESSION['lang']) && in_array($_SESSION['lang'], $supported, true)) return $_SESSION['lang'];
  if (!empty($_COOKIE['lang']) && in_array($_COOKIE['lang'], $supported, true)) {
    $_SESSION['lang'] = $_COOKIE['lang'];
    return $_COOKIE['lang'];
  }
  $l = detect_browser_lang();
  $_SESSION['lang'] = $l;
  return $l;
}

function set_lang($lang) {
  $supported = array_keys(supported_languages());
  if (!in_array($lang, $supported, true)) $lang = 'en';
  $_SESSION['lang'] = $lang;
  $secure = defined('COOKIE_SECURE') ? COOKIE_SECURE : false;
  setcookie('lang', $lang, time() + 60*60*24*365, '/', '', $secure, false);
}

function t($key, $vars = []) {
  $lang = get_lang();
  $dict = translations();
  $text = (isset($dict[$lang][$key])) ? $dict[$lang][$key] : ((isset($dict['en'][$key])) ? $dict['en'][$key] : $key);
  foreach ($vars as $k => $v) {
    $text = str_replace('{' . $k . '}', (string)$v, $text);
  }
  return $text;
}

